fields.InputDefinition:
{
  "goal": "You are already logged in at http://localhost:4200. Go to the Home landing page (Home icon/logo or application switcher dropdown). Look for the Quick Access toggle — a fixed circular button with a bolt icon (bottom/side of the page). Click it to open the right-hand 'Quick Access' sidebar, which shows sections like Notifications, Favorites, and Recent (or a compact 'No quick access items' empty state if you have none). Then click the sidebar's close (x) button and verify the sidebar collapses back. Success is opening and closing the Quick Access sidebar; if the FAB is absent because there is no quick-access content, seeing the Home page render cleanly with no sidebar is an acceptable pass. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Clicking the Quick Access bolt button opens the right sidebar showing Favorites/Recent/Notifications sections OR a valid 'No quick access items' empty state (or the FAB is legitimately absent when there is no content)",
    "Clicking the sidebar close (x) collapses the sidebar again",
    "No error messages, blank screens, or crash pages"
  ]
}
